files.content:
[hidden] { display: none !important; }

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: #2b2b3c;
  color: #e0e0e0;
  font-family: 'Courier New', monospace;
  font-size: 18px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.quiz-card {
  background-color: #3c3c4e;
  border: 4px solid #f0c040;
  border-radius: 0;
  padding: 32px;
  width: 100%;
  max-width: 480px;
  box-shadow: 8px 8px 0 #1a1a28;
  text-align: center;
}

.title {
  font-size: 1.8rem;
  color: #f0c040;
  text-shadow: 2px 2px 0 #1a1a28;
  margin-bottom: 24px;
  letter-spacing: 2px;
}

.question {
  font-size: 2rem;
  margin-bottom: 16px;
  min-height: 2.4rem;
}

.score-label {
  font-size: 1.2rem;
  margin-bottom: 24px;
  color: #a0a0b8;
}

#score {
  color: #f0c040;
  font-weight: bold;
}

.answers {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
}

.answer-btn {
  background-color: #4a4a5e;
  color: #e0e0e0;
  border: 3px solid #6a6a80;
  padding: 12px 24px;
  font-size: 1.5rem;
  font-family: inherit;
  cursor: pointer;
  min-width: 100px;
  transition: background-color 0.1s, border-color 0.1s, transform 0.1s;
}

.answer-btn:hover:not(:disabled) {
  background-color: #5a5a70;
  border-color: #f0c040;
}

.answer-btn:active:not(:disabled) {
  transform: translate(2px, 2px);
  background-color: #3a3a4e;
}

.answer-btn:focus-visible {
  outline: 3px solid #f0c040;
  outline-offset: 2px;
}

.answer-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
}

.control-btn {
  background-color: #f0c040;
  color: #1a1a28;
  border: 3px solid #f0c040;
  padding: 10px 20px;
  font-size: 1.2rem;
  font-family: inherit;
  font-weight: bold;
  cursor: pointer;
  transition: background-color 0.1s, transform 0.1s;
}

.control-btn:hover {
  background-color: #f8d860;
  border-color: #f8d860;
}

.control-btn:active {
  transform: translate(2px, 2px);
  background-color: #d0a030;
}

.control-btn:focus-visible {
  outline: 3px solid #e0e0e0;
  outline-offset: 2px;
}

@media (max-width: 400px) {
  .quiz-card {
    padding: 20px;
  }
  .question {
    font-size: 1.6rem;
  }
  .answer-btn {
    padding: 10px 16px;
    font-size: 1.3rem;
    min-width: 80px;
  }
}

(function() {
  'use strict';

  const questionEl = document.getElementById('question');
  const answerA = document.getElementById('answer-a');
  const answerB = document.getElementById('answer-b');
  const scoreEl = document.getElementById('score');
  const nextBtn = document.getElementById('next');
  const restartBtn = document.getElementById('restart');

  let score = 0;
  let currentQuestion = 0;
  let answered = false;

  const questions = [
    { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
    { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
  ];

  function renderQuestion() {
    const q = questions[currentQuestion];
    questionEl.textContent = q.text;
    answerA.textContent = q.a;
    answerB.textContent = q.b;
    answerA.disabled = false;
    answerB.disabled = false;
    answered = false;
  }

  function updateScore() {
    scoreEl.textContent = score;
  }

  function handleAnswer(choice) {
    if (answered || currentQuestion >= questions.length) return;
    answered = true;
    answerA.disabled = true;
    answerB.disabled = true;
    if (questions[currentQuestion].correct === choice) {
      score += 1;
      updateScore();
    }
  }

  function handleNext() {
    if (!answered) return;
    if (currentQuestion < questions.length - 1) {
      currentQuestion += 1;
      renderQuestion();
    } else {
      questionEl.textContent = 'Finished';
      answerA.disabled = true;
      answerB.disabled = true;
    }
  }

  function handleRestart() {
    currentQuestion = 0;
    score = 0;
    updateScore();
    renderQuestion();
  }

  answerA.addEventListener('click', function() { handleAnswer('a'); });
  answerB.addEventListener('click', function() { handleAnswer('b'); });
  nextBtn.addEventListener('click', handleNext);
  restartBtn.addEventListener('click', handleRestart);

  renderQuestion();
  updateScore();
})();
